package pagos;
import java.math.BigDecimal;import java.net.URI;import java.time.LocalDateTime;
public record SolicitudCheckout(long ordenId,long reservaId,BigDecimal importe,String moneda,String descripcion,String referencia,LocalDateTime vencimiento,URI retornoExitoso,URI retornoPendiente,URI retornoFallido,URI notificacionUrl,String claveIdempotencia){public SolicitudCheckout{if(ordenId<=0||reservaId<=0)throw new IllegalArgumentException("La orden y la reserva son obligatorias.");if(importe==null||importe.signum()<=0)throw new IllegalArgumentException("El importe debe ser positivo.");if(moneda==null||moneda.isBlank()||referencia==null||referencia.isBlank()||claveIdempotencia==null||claveIdempotencia.isBlank())throw new IllegalArgumentException("Moneda, referencia e idempotencia son obligatorias.");}}
